
import { StudioProApi } from "@mendix/extensions-api";
import { ConsumedMCPService } from "../../types/consumedMCPService";
import { createStudioProLogger } from "../../config/logger";

export const handleConsumedMCPServiceChangeValue = (studioPro: StudioProApi, field: keyof ConsumedMCPService, consumedMCPService: ConsumedMCPService, setConsumedMCPService: React.Dispatch<React.SetStateAction<ConsumedMCPService>>, documentId: string) => async (
    value: string
) => {
    const updatedConsumedMCPService = { ...consumedMCPService, [field]: value }
    setConsumedMCPService(updatedConsumedMCPService);
    updateConsumedMCPServiceDocument(studioPro, updatedConsumedMCPService, documentId);

};

const updateConsumedMCPServiceDocument = async (studioPro: StudioProApi, consumedMCPService: ConsumedMCPService, documentId: string) => {
    const logger = createStudioProLogger(studioPro);
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, consumedMCPService);
    } catch (error) {
        logger.error("Failed to save document:", error);
        studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message
        });
    }
};
